async function chargeCustomer(orderId, amount) {
  // 1. Ask the registry for healthy instances only
  const instances = await registry.getHealthyInstances("payment-service");

  if (instances.length === 0) {
    throw new Error("no healthy payment instances available");
  }

  // 2. Pick one, here a simple random pick
  const target = instances[Math.floor(Math.random() * instances.length)];

  // 3. Call it directly, with a short timeout and one retry
  try {
    return await httpClient.post(
      `http://${target.host}:${target.port}/charge`,
      { orderId, amount },
      { timeout: 2000 }
    );
  } catch (err) {
    const fallback = instances.find(i => i.host !== target.host);
    if (!fallback) throw err;
    return await httpClient.post(
      `http://${fallback.host}:${fallback.port}/charge`,
      { orderId, amount },
      { timeout: 2000 }
    );
  }
}

